// src/index.js
import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";
import { FRONT_BASE } from "./api/config";

(async function bootstrap() {
  const base = (FRONT_BASE || "/").replace(/\/+$/, "");

  // ✅ 전역 location 대신 안전 참조 사용
  const host = (typeof window !== "undefined" && window.location)
    ? window.location.hostname
    : "";

  // localhost / 127.0.0.1 / 0.0.0.0 전부 로컬 취급
  const isLocal = /^(localhost|127\.0\.0\.1|0\.0\.0\.0)$/.test(host);

  // ✅ 로컬은 루트 스코프, 배포는 /woodenpages 스코프
  const swUrl   = isLocal ? "/mockServiceWorker.js"         : `${base}/mockServiceWorker.js`;
  const swScope = isLocal ? "/"                             : `${base}/`;

  await worker.start({
    serviceWorker: { url: swUrl, options: { scope: swScope } },
    onUnhandledRequest: "warn",
  });
  console.log("[MSW] registered:", { url: swUrl, scope: swScope });

  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();
